'use strict';

var linspace = require( '@stdlib/array/linspace' );
var iterCartesianProduct = require( './../lib' );

// Create array-like objects:
var x1 = linspace( 0, 2, 3 );
var x2 = linspace( 3, 5, 3 );

// Create an iterator which iterates over the Cartesian product:
var it = iterCartesianProduct( x1, x2 );

// Perform manual iteration...
var v;
while ( true ) {
	v = it.next();
	if ( v.done ) {
		break;
	}
	console.log( v.value );
}
